def attach_replacements(guides,lessons):
    known={l['id']:l for l in lessons}
    for guide in guides:
        rows=PATCHES.get(guide['lessonId'])
        if rows is None:continue
        old=known[guide['lessonId']]['exercises']
        assert len(rows)==len(old),(guide['lessonId'],len(rows),len(old))
        guide['replacements']=[]
        for base,patch in zip(old,rows):
            replacement=deepcopy(base);replacement.update(patch)
            replacement['revision']=base.get('revision',0)+1
            guide['replacements'].append(replacement)
